// ============================================================
// REGEN Layout — Sidebar + Header + Main content shell
// ============================================================

import React, { useState } from "react";
import { NavLink, useLocation } from "react-router-dom";
import { cn } from "../../utils";

const NAV_ITEMS = [
  { path: "/", label: "Dashboard", icon: "⊞" },
  { path: "/network", label: "Network", icon: "◈" },
  { path: "/track-circuits", label: "Track Circuits", icon: "⊡" },
  { path: "/assets", label: "Assets", icon: "◧" },
  { path: "/fbg-monitoring", label: "FBG Monitoring", icon: "⊕" },
  { path: "/alerts", label: "Alerts", icon: "⚠" },
  { path: "/inspections", label: "Inspections", icon: "◎" },
  { path: "/maintenance", label: "Maintenance", icon: "⚙" },
  { path: "/reports", label: "Reports", icon: "▤" },
];

interface LayoutProps {
  children: React.ReactNode;
  liveStatus?: { faults: number; alerts: number };
}

export function Layout({ children, liveStatus }: LayoutProps) {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const location = useLocation();

  const currentPage = NAV_ITEMS.find(n => n.path === location.pathname)?.label ?? "Dashboard";

  return (
    <div className="flex h-screen bg-[#F5F7FA] overflow-hidden">
      {/* Sidebar */}
      <aside className={cn(
        "fixed inset-y-0 left-0 z-40 flex flex-col w-56 bg-[#0B1F33] transition-transform duration-200",
        "lg:static lg:translate-x-0",
        sidebarOpen ? "translate-x-0" : "-translate-x-full"
      )}>
        {/* Logo */}
        <div className="flex flex-col px-5 pt-5 pb-4 border-b border-white/10">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-[#145DA0] rounded flex items-center justify-center flex-shrink-0">
              <span className="text-white font-black text-sm">R</span>
            </div>
            <div>
              <div className="text-white font-black text-base leading-none tracking-wide">REGEN</div>
              <div className="text-[#00A6C7] text-[10px] font-medium leading-tight mt-0.5">Railway Infrastructure</div>
            </div>
          </div>
          <div className="mt-3 px-2 py-1 bg-amber-500/20 border border-amber-500/30 rounded text-[10px] text-amber-300 font-semibold text-center uppercase tracking-wide">
            Simulation Mode
          </div>
        </div>

        {/* Nav */}
        <nav className="flex-1 overflow-y-auto py-3 px-2">
          {NAV_ITEMS.map(item => (
            <NavLink
              key={item.path}
              to={item.path}
              end={item.path === "/"}
              className={({ isActive }) => cn(
                "flex items-center gap-3 px-3 py-2.5 rounded text-sm font-medium transition-colors mb-0.5",
                isActive
                  ? "bg-[#145DA0] text-white"
                  : "text-white/70 hover:text-white hover:bg-white/10"
              )}
              onClick={() => setSidebarOpen(false)}
            >
              <span className="text-base w-5 text-center">{item.icon}</span>
              <span>{item.label}</span>
              {item.label === "Alerts" && liveStatus && liveStatus.alerts > 0 && (
                <span className="ml-auto bg-red-500 text-white text-xs font-bold px-1.5 py-0.5 rounded-full leading-none">
                  {liveStatus.alerts}
                </span>
              )}
              {item.label === "Track Circuits" && liveStatus && liveStatus.faults > 0 && (
                <span className="ml-auto bg-amber-500 text-white text-xs font-bold px-1.5 py-0.5 rounded-full leading-none">
                  {liveStatus.faults}
                </span>
              )}
            </NavLink>
          ))}
        </nav>

        {/* Footer */}
        <div className="px-4 py-3 border-t border-white/10">
          <div className="text-[10px] text-white/40 leading-snug">
            REGEN MVP v1.0
            <br />Not for safety-critical use
          </div>
        </div>
      </aside>

      {/* Sidebar overlay for mobile */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 z-30 bg-black/50 lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Main */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Top header */}
        <header className="flex items-center gap-4 px-4 lg:px-6 h-14 bg-white border-b border-[#D9E1E8] flex-shrink-0">
          {/* Mobile menu */}
          <button
            className="lg:hidden p-1.5 rounded hover:bg-[#F5F7FA] text-[#64748B]"
            onClick={() => setSidebarOpen(true)}
          >
            <span className="text-lg">☰</span>
          </button>

          {/* Breadcrumb */}
          <div className="flex items-center gap-2 text-sm">
            <span className="text-[#64748B] hidden sm:inline">REGEN</span>
            <span className="text-[#D9E1E8] hidden sm:inline">/</span>
            <span className="font-semibold text-[#172B3A]">{currentPage}</span>
          </div>

          {/* Spacer */}
          <div className="flex-1" />

          {/* Live indicators */}
          {liveStatus && (
            <div className="flex items-center gap-3">
              {liveStatus.faults > 0 && (
                <div className="flex items-center gap-1.5 text-xs">
                  <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
                  <span className="text-red-600 font-semibold hidden sm:inline">{liveStatus.faults} Fault{liveStatus.faults !== 1 ? "s" : ""}</span>
                </div>
              )}
              <div className="flex items-center gap-1.5 text-xs">
                <span className="w-2 h-2 bg-green-500 rounded-full" />
                <span className="text-[#64748B] hidden sm:inline">Live</span>
              </div>
            </div>
          )}

          {/* Time */}
          <LiveClock />
        </header>

        {/* Page content */}
        <main className="flex-1 overflow-y-auto">
          <div className="p-4 lg:p-6 max-w-screen-2xl mx-auto">
            {children}
          </div>
        </main>
      </div>
    </div>
  );
}

function LiveClock() {
  const [time, setTime] = React.useState(new Date());
  React.useEffect(() => {
    const t = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(t);
  }, []);
  return (
    <div className="text-xs text-[#64748B] font-mono tabular-nums hidden md:block">
      {time.toLocaleTimeString("en-ZA", { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false })}
    </div>
  );
}
