import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Card, SectionHeader, SimulatedDataBanner, TrackCircuitStatusBadge, Button } from "../components/ui";
import { RAILWAY_LINES, SECTIONS, TRACK_CIRCUITS, ASSETS, FBG_SENSORS } from "../store/dataStore";
import { cn } from "../utils";
import type { TrackCircuit } from "../types";

// SVG colour map
const TC_COLORS: Record<string, string> = {
