      ]
    },
  ]
};

// TC positions on the SVG
const TC_POSITIONS: Record<string, { x: number; y: number; lineY: number }> = {
  "tc-001": { x: 90, y: 80, lineY: 80 }, "tc-002": { x: 130, y: 80, lineY: 80 },
