  "tc-009": { x: 405, y: 80, lineY: 80 }, "tc-010": { x: 440, y: 80, lineY: 80 },
  "tc-011": { x: 480, y: 80, lineY: 80 }, "tc-021": { x: 535, y: 80, lineY: 80 },
  "tc-013": { x: 580, y: 80, lineY: 80 },
  "tc-014": { x: 100, y: 200, lineY: 200 }, "tc-015": { x: 170, y: 200, lineY: 200 },
  "tc-016": { x: 270, y: 200, lineY: 200 }, "tc-017": { x: 350, y: 200, lineY: 200 },
  "tc-018": { x: 105, y: 320, lineY: 320 }, "tc-019": { x: 250, y: 320, lineY: 320 },
  "tc-020": { x: 460, y: 320, lineY: 320 },
};

const STATION_LABELS = [
  { x: 60, y: 75, label: "JHB Central", line: 0 },
  { x: 200, y: 75, label: "Germiston Jct", line: 0 },
  { x: 335, y: 75, label: "Boksburg N", line: 0 },
  { x: 455, y: 75, label: "Benoni", line: 0 },
  { x: 600, y: 75, label: "Daveyton", line: 0 },
  { x: 60, y: 195, label: "Cape Town", line: 1 },
  { x: 215, y: 195, label: "Bellville", line: 1 },
  { x: 365, y: 195, label: "Kraaifontein", line: 1 },
  { x: 555, y: 195, label: "Paarl", line: 1 },
  { x: 60, y: 315, label: "Durban Hbr", line: 2 },
  { x: 195, y: 315, label: "Rossburgh", line: 2 },
  { x: 385, y: 315, label: "Amanzimtoti", line: 2 },
  { x: 580, y: 315, label: "Umkomaas", line: 2 },
];

export function NetworkPage() {
  const navigate = useNavigate();
  const [selectedTc, setSelectedTc] = useState<TrackCircuit | null>(null);
  const [hoveredTc, setHoveredTc] = useState<string | null>(null);
  const [filterLine, setFilterLine] = useState<string>("all");

  const tcs = TRACK_CIRCUITS;

  const getTC = (id: string) => tcs.find(t => t.id === id);

  const filteredTcs = filterLine === "all" ? tcs : tcs.filter(t => t.railway_line_id === filterLine);

  const lineCounts = RAILWAY_LINES.map(line => ({
    ...line,
    normal: tcs.filter(t => t.railway_line_id === line.id && t.status === "NORMAL").length,
    occupied: tcs.filter(t => t.railway_line_id === line.id && t.status === "OCCUPIED").length,
    fault: tcs.filter(t => t.railway_line_id === line.id && (t.status === "FAULT" || t.status === "UNKNOWN" || t.status === "OFFLINE")).length,
  }));

  return (
    <div className="space-y-4">
      <SimulatedDataBanner />
      <div className="flex items-start justify-between">
        <div>
          <h1 className="text-xl font-bold text-[#172B3A]">Railway Network Map</h1>
          <p className="text-sm text-[#64748B] mt-1">Simplified operational overview — read-only monitoring</p>
        </div>
        <select
          value={filterLine}
          onChange={e => setFilterLine(e.target.value)}
          className="border border-[#D9E1E8] rounded px-3 py-1.5 text-sm text-[#172B3A] bg-white focus:outline-none focus:ring-2 focus:ring-[#145DA0]"
        >
          <option value="all">All Lines</option>
          {RAILWAY_LINES.map(l => <option key={l.id} value={l.id}>{l.name}</option>)}
        </select>
      </div>

      {/* Line summary cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        {lineCounts.map(line => (
          <Card key={line.id} className={cn(filterLine === line.id && "ring-2 ring-[#145DA0]")} hover onClick={() => setFilterLine(filterLine === line.id ? "all" : line.id)}>
            <div className="flex items-center gap-2 mb-2">
              <div className="w-3 h-3 rounded-full" style={{ backgroundColor: NETWORK_LAYOUT.lines.find(l => l.id === line.id)?.color }} />
              <span className="text-sm font-semibold text-[#172B3A]">{line.name}</span>
            </div>
            <div className="text-xs text-[#64748B] mb-2">{line.total_length_km} km · {line.status}</div>
            <div className="flex gap-3 text-xs">
              <span className="text-green-600 font-semibold">✓ {line.normal} Normal</span>
              <span className="text-blue-600 font-semibold">● {line.occupied} Occupied</span>
              {line.fault > 0 && <span className="text-red-600 font-semibold">⚠ {line.fault} Fault</span>}
            </div>
          </Card>
        ))}
      </div>

      {/* SVG Map */}
      <Card padding={false} className="overflow-hidden">
        <div className="px-4 pt-4 pb-2 border-b border-[#D9E1E8] flex items-center justify-between">
          <div>
            <h2 className="text-sm font-semibold text-[#172B3A]">Network Diagram</h2>
            <p className="text-xs text-[#64748B]">Schematic layout — not to scale. Click track circuits for detail.</p>
          </div>
          {/* Legend */}
          <div className="flex items-center gap-3 flex-wrap">
            {Object.entries(TC_COLORS).map(([s, c]) => (
              <div key={s} className="flex items-center gap-1">
                <div className="w-3 h-3 rounded-full border border-white/30" style={{ backgroundColor: c }} />
                <span className="text-xs text-[#64748B]">{s}</span>
              </div>
            ))}
          </div>
        </div>
        <div className="overflow-x-auto">
          <svg viewBox="0 0 680 420" className="w-full min-w-[600px]" style={{ minHeight: 380 }}>
            <rect width="680" height="420" fill="#F5F7FA" />

            {/* Grid lines */}
            {[100,200,300,400].map(y => (
              <line key={y} x1="0" y1={y} x2="680" y2={y} stroke="#E2E8F0" strokeWidth="0.5" />
            ))}

            {/* Railway lines */}
            {NETWORK_LAYOUT.lines.map((line, li) => {
              const secs = line.sections;
              if (filterLine !== "all" && filterLine !== line.id) return null;
              return (
                <g key={line.id}>
                  {secs.map(sec => (
                    <line key={sec.id}
                      x1={sec.x1} y1={line.y} x2={sec.x2} y2={line.y}
                      stroke={line.color} strokeWidth="5" strokeLinecap="round" opacity="0.7"
                    />
                  ))}
                  {/* Section labels */}
                  {secs.map(sec => (
                    <text key={sec.id+"-lbl"} x={(sec.x1 + sec.x2) / 2} y={line.y + 18}
                      textAnchor="middle" fontSize="8" fill="#64748B" fontFamily="monospace">
                      {sec.code}
                    </text>
                  ))}
                </g>
              );
            })}

            {/* Station markers */}
            {STATION_LABELS.map((s, i) => {
              const lineObj = NETWORK_LAYOUT.lines[s.line];
              if (filterLine !== "all" && filterLine !== RAILWAY_LINES[s.line]?.id) return null;
              return (
                <g key={i}>
                  <circle cx={s.x} cy={s.y} r="5" fill="white" stroke={lineObj.color} strokeWidth="2" />
                  <text x={s.x} y={s.y - 9} textAnchor="middle" fontSize="8" fill="#172B3A" fontWeight="600" fontFamily="sans-serif">
                    {s.label}
                  </text>
                </g>
              );
            })}

            {/* TC markers */}
            {Object.entries(TC_POSITIONS).map(([tcId, pos]) => {
              const tc = getTC(tcId);
              if (!tc) return null;
              const lineObj = NETWORK_LAYOUT.lines.find(l => l.sections.some(s => s.id === tc.section_id));
              if (filterLine !== "all" && filterLine !== tc.railway_line_id) return null;
              const color = TC_COLORS[tc.status] ?? "#6B7280";
              const isSelected = selectedTc?.id === tcId;
              const isHovered = hoveredTc === tcId;
              const hasFault = tc.status === "FAULT" || tc.status === "UNKNOWN";
              return (
                <g key={tcId}
                  onClick={() => setSelectedTc(isSelected ? null : tc)}
                  onMouseEnter={() => setHoveredTc(tcId)}
                  onMouseLeave={() => setHoveredTc(null)}
                  style={{ cursor: "pointer" }}
                >
                  {hasFault && (
                    <circle cx={pos.x} cy={pos.y} r="12" fill={color} opacity="0.2">
                      <animate attributeName="r" values="8;14;8" dur="2s" repeatCount="indefinite" />
                    </circle>
                  )}
                  <circle cx={pos.x} cy={pos.y} r={isSelected || isHovered ? 9 : 7}
                    fill={color}
                    stroke="white"
