            <div className="bg-red-50 border border-red-200 rounded px-3 py-2 text-xs text-red-800 mb-3">
              <span className="font-semibold">Fault: </span>{selectedTc.fault_description}
            </div>
          )}
          <div className="flex gap-2">
            <Button size="sm" variant="primary" onClick={() => navigate(`/track-circuits?id=${selectedTc.id}`)}>Track Circuit Detail</Button>
            <Button size="sm" onClick={() => navigate(`/assets?tc=${selectedTc.id}`)}>Related Assets</Button>
          </div>
        </Card>
      )}

      {/* Section asset summary */}
      <Card>
        <SectionHeader title="Section Overview" subtitle="Assets and sensors by section" />
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
