                const secTCs = TRACK_CIRCUITS.filter(t => t.section_id === sec.id);
                const secAssets = ASSETS.filter(a => a.section_id === sec.id);
                const secSensors = FBG_SENSORS.filter(s => secAssets.some(a => a.id === s.asset_id));
                const faults = secTCs.filter(t => t.status === "FAULT" || t.status === "UNKNOWN" || t.status === "OFFLINE").length;
