import React, { useEffect, useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import {
  Card, SectionHeader, PageHeader, SimulatedDataBanner,
  TrackCircuitStatusBadge, Button, DataRow, Timeline, Select
} from "../components/ui";
import { fetchTrackCircuits, fetchTrackCircuitEvents } from "../store/dataStore";
import { RAILWAY_LINES, SECTIONS } from "../store/dataStore";
import { formatTimestamp, formatTime, timeAgo } from "../utils";
import type { TrackCircuit, TrackCircuitEvent } from "../types";
import { cn } from "../utils";

const STATUS_STEPS = [
  { key: "NORMAL", label: "Normal" },
  { key: "OCCUPIED", label: "Occupied" },
  { key: "FAULT", label: "Fault Detected" },
  { key: "INVESTIGATION", label: "Investigation" },
  { key: "ASSIGNED", label: "Technician Assigned" },
  { key: "RESOLVED", label: "Resolved" },
  { key: "VERIFIED", label: "Verified" },
];

export function TrackCircuitsPage() {
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const [circuits, setCircuits] = useState<TrackCircuit[]>([]);
  const [selected, setSelected] = useState<TrackCircuit | null>(null);
  const [events, setEvents] = useState<TrackCircuitEvent[]>([]);
  const [filterStatus, setFilterStatus] = useState("all");
  const [filterLine, setFilterLine] = useState("all");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchTrackCircuits().then(data => {
      setCircuits(data);
      setLoading(false);
      const paramId = params.get("id");
      if (paramId) {
        const found = data.find(tc => tc.id === paramId || tc.track_circuit_id === paramId);
        if (found) selectCircuit(found);
      } else {
        // Auto-select TC-021 for demo
        const demo = data.find(tc => tc.track_circuit_id === "TC-021");
        if (demo) selectCircuit(demo);
      }
    });
  }, []);

  const selectCircuit = async (tc: TrackCircuit) => {
    setSelected(tc);
    const evts = await fetchTrackCircuitEvents(tc.id);
    setEvents(evts);
  };

  const filtered = circuits.filter(tc => {
    if (filterStatus !== "all" && tc.status !== filterStatus) return false;
    if (filterLine !== "all" && tc.railway_line_id !== filterLine) return false;
    return true;
  });

  const buildTimeline = (tc: TrackCircuit) => {
    const evtItems = events.slice(0, 8).map(evt => ({
      id: evt.id,
      label: evt.new_status === "FAULT" ? "Fault Detected" : evt.new_status === "OCCUPIED" ? "Occupied" :
             evt.new_status === "NORMAL" ? "Normal" : evt.new_status === "UNKNOWN" ? "Status Unknown" : evt.event_type,
      description: evt.description,
      timestamp: formatTime(evt.timestamp),
      status: (evt.new_status === "FAULT" ? "fault" :
               evt.new_status === "NORMAL" ? "completed" :
               evt.new_status === "OCCUPIED" ? "active" : "pending") as "completed" | "active" | "pending" | "fault",
    }));
    return evtItems;
  };

  return (
    <div className="space-y-4">
      <SimulatedDataBanner />
      <PageHeader
        title="Track Circuit Monitoring"
        subtitle="Read-only track circuit status. REGEN receives status information — it does not control track circuits."
      >
        <div className="flex gap-2">
          <Select value={filterLine} onChange={e => setFilterLine(e.target.value)}>
            <option value="all">All Lines</option>
            {RAILWAY_LINES.map(l => <option key={l.id} value={l.id}>{l.name}</option>)}
          </Select>
          <Select value={filterStatus} onChange={e => setFilterStatus(e.target.value)}>
            <option value="all">All Status</option>
            <option value="NORMAL">Normal</option>
            <option value="OCCUPIED">Occupied</option>
            <option value="FAULT">Fault</option>
            <option value="UNKNOWN">Unknown</option>
            <option value="OFFLINE">Offline</option>
          </Select>
        </div>
      </PageHeader>

      <div className="grid grid-cols-1 lg:grid-cols-5 gap-4">
        {/* Left: circuit list */}
        <div className="lg:col-span-2">
          <Card padding={false}>
            <div className="px-4 py-3 border-b border-[#D9E1E8]">
              <div className="text-sm font-semibold text-[#172B3A]">Track Circuits ({filtered.length})</div>
            </div>
            <div className="divide-y divide-[#D9E1E8] max-h-[70vh] overflow-y-auto">
              {loading && (
                <div className="px-4 py-8 text-center text-xs text-[#64748B]">Loading...</div>
              )}
              {!loading && filtered.length === 0 && (
                <div className="px-4 py-8 text-center text-xs text-[#64748B]">No circuits match filter</div>
              )}
              {filtered.map(tc => (
                <div
                  key={tc.id}
                  className={cn(
                    "px-4 py-3 cursor-pointer hover:bg-[#F5F7FA] transition-colors",
                    selected?.id === tc.id && "bg-blue-50 border-l-3 border-[#145DA0]"
                  )}
                  onClick={() => selectCircuit(tc)}
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-bold text-[#172B3A] font-mono">{tc.track_circuit_id}</span>
                        {tc.fault_status && <span className="w-2 h-2 rounded-full bg-red-500 flex-shrink-0 animate-pulse" />}
                      </div>
                      <div className="text-xs text-[#64748B] mt-0.5 truncate">{tc.location_description}</div>
                      <div className="text-xs text-[#64748B] font-mono">{tc.signal_relationship}</div>
                    </div>
                    <TrackCircuitStatusBadge status={tc.status} />
                  </div>
                  {tc.fault_description && (
                    <div className="mt-1.5 text-xs text-red-600 bg-red-50 rounded px-2 py-1">
                      {tc.fault_description.substring(0, 60)}...
                    </div>
                  )}
                </div>
              ))}
            </div>
          </Card>
        </div>

        {/* Right: detail */}
        <div className="lg:col-span-3 space-y-4">
          {selected ? (
            <>
              {/* TC Header */}
              <Card>
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <div className="flex items-center gap-3">
                      <span className="text-2xl font-black text-[#172B3A] font-mono">{selected.track_circuit_id}</span>
                      <TrackCircuitStatusBadge status={selected.status} size="md" />
                    </div>
                    <p className="text-sm text-[#64748B] mt-1">{selected.location_description}</p>
                  </div>
                  <div className="text-right text-xs text-[#64748B]">
                    <div>Last update</div>
                    <div className="font-semibold text-[#172B3A]">{formatTime(selected.last_update)}</div>
                    <div>{timeAgo(selected.last_update)}</div>
                  </div>
                </div>

                {selected.fault_description && (
