                          isDone ? "bg-green-100 text-green-700 border-green-300" :
                          "bg-[#F5F7FA] text-[#64748B] border-[#D9E1E8]"
                        )}>
                          {step.label}
                        </div>
                        {i < STATUS_STEPS.length - 1 && <span className="text-[#D9E1E8]">→</span>}
                      </React.Fragment>
                    );
                  })}
                </div>
              </Card>

              {/* Event timeline */}
              <Card>
                <SectionHeader title="Event Timeline" subtitle={`${events.length} events recorded for ${selected.track_circuit_id}`} />
                {events.length > 0 ? (
                  <Timeline items={buildTimeline(selected)} />
                ) : (
                  <div className="text-xs text-[#64748B] text-center py-4">No events recorded</div>
                )}
              </Card>
            </>
          ) : (
            <Card>
              <div className="text-center py-12 text-[#64748B]">
                <div className="text-3xl mb-3">⊡</div>
                <div className="text-sm font-semibold">Select a track circuit</div>
                <div className="text-xs mt-1">Click a circuit from the list to view details and event history</div>
              </div>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}
