        if (found) selectSensor(found);
      } else if (paramAsset) {
        const found = data.find(s => s.asset_id === paramAsset);
        if (found) selectSensor(found);
      } else {
        const demo = data.find(s => s.sensor_id === "FBG-00021");
        if (demo) selectSensor(demo);
