import React, { useEffect, useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import {
  Card, PageHeader, SimulatedDataBanner, Button,
  AlertPriorityBadge, TrackCircuitStatusBadge, RiskBadge,
  AssetConditionBadge, TrendBadge, Select, Modal, Tabs
} from "../components/ui";
import { fetchAlerts, updateAlertStatus, fetchInspections, createInspection } from "../store/dataStore";
import { formatTimestamp, timeAgo, cn } from "../utils";
import type { Alert } from "../types";

const STATUS_COLORS: Record<string, string> = {
  OPEN: "text-red-600 bg-red-50 border-red-200",
  ACKNOWLEDGED: "text-blue-600 bg-blue-50 border-blue-200",
  INVESTIGATING: "text-amber-600 bg-amber-50 border-amber-200",
  RESOLVED: "text-green-600 bg-green-50 border-green-200",
  CLOSED: "text-gray-500 bg-gray-50 border-gray-200",
};

const SOURCE_COLORS: Record<string, string> = {
  TRACK_CIRCUIT: "text-blue-700 bg-blue-50", FBG_SENSOR: "text-purple-700 bg-purple-50",
  COMBINED: "text-orange-700 bg-orange-50", COMMUNICATION: "text-gray-700 bg-gray-100",
  ASSET: "text-teal-700 bg-teal-50", MAINTENANCE: "text-green-700 bg-green-50",
};

export function AlertsPage() {
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [selected, setSelected] = useState<Alert | null>(null);
  const [filterStatus, setFilterStatus] = useState("active");
  const [filterPriority, setFilterPriority] = useState("all");
  const [filterSource, setFilterSource] = useState("all");
  const [loading, setLoading] = useState(true);
  const [inspectionModal, setInspectionModal] = useState(false);
  const [actionFeedback, setActionFeedback] = useState<string | null>(null);

  const load = () => {
    fetchAlerts().then(data => {
      setAlerts(data);
      setLoading(false);
      const paramId = params.get("id");
      if (paramId) {
        const found = data.find(a => a.id === paramId || a.alert_id === paramId);
        if (found) setSelected(found);
      } else {
        const demo = data.find(a => a.alert_id === "ALERT-001");
        if (demo) setSelected(demo);
      }
    });
  };

  useEffect(load, []);

  const filtered = alerts.filter(a => {
    if (filterStatus === "active" && (a.status === "CLOSED" || a.status === "RESOLVED")) return false;
    if (filterStatus === "closed" && a.status !== "CLOSED" && a.status !== "RESOLVED") return false;
    if (filterPriority !== "all" && a.priority !== filterPriority) return false;
    if (filterSource !== "all" && a.source !== filterSource) return false;
    return true;
  });

  const handleAcknowledge = async (alert: Alert) => {
    await updateAlertStatus(alert.id, "ACKNOWLEDGED", "Control Room Operator");
    setActionFeedback("Alert acknowledged");
    load();
    setTimeout(() => setActionFeedback(null), 3000);
  };

  const handleInvestigate = async (alert: Alert) => {
    await updateAlertStatus(alert.id, "INVESTIGATING");
    setActionFeedback("Alert set to Investigating");
    load();
    setTimeout(() => setActionFeedback(null), 3000);
  };

  const handleCreateInspection = async () => {
    if (!selected) return;
    await createInspection({
      alert_id: selected.id,
      asset_id: selected.asset_id ?? "",
      track_circuit_id: selected.track_circuit_id ?? undefined,
      sensor_id: selected.sensor_id ?? undefined,
      title: `Inspection — ${selected.title}`,
      reason: `Created from Alert ${selected.alert_id}: ${selected.description.substring(0, 100)}`,
      priority: selected.priority,
      location_description: (selected as any).asset?.location_description ?? "Location from alert",
    });
    setInspectionModal(false);
    setActionFeedback("Inspection task created");
    setTimeout(() => setActionFeedback(null), 3000);
    navigate("/inspections");
  };

  const countByStatus = (s: string) => alerts.filter(a => a.status === s).length;

  return (
    <div className="space-y-4">
      <SimulatedDataBanner />
      <PageHeader title="Alert Engine" subtitle="Simulated alerts from track circuits, FBG sensors, assets and maintenance">
        <div className="flex gap-2 flex-wrap">
          <Select value={filterStatus} onChange={e => setFilterStatus(e.target.value)}>
            <option value="active">Active Alerts</option>
            <option value="all">All Alerts</option>
            <option value="closed">Closed / Resolved</option>
          </Select>
          <Select value={filterPriority} onChange={e => setFilterPriority(e.target.value)}>
            <option value="all">All Priority</option>
            <option value="CRITICAL">Critical</option>
            <option value="HIGH">High</option>
            <option value="WARNING">Warning</option>
            <option value="NORMAL">Normal</option>
          </Select>
          <Select value={filterSource} onChange={e => setFilterSource(e.target.value)}>
            <option value="all">All Sources</option>
            <option value="COMBINED">Combined</option>
            <option value="TRACK_CIRCUIT">Track Circuit</option>
            <option value="FBG_SENSOR">FBG Sensor</option>
            <option value="ASSET">Asset</option>
            <option value="COMMUNICATION">Communication</option>
          </Select>
        </div>
      </PageHeader>

      {/* Stats row */}
      <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
        {[
          { label: "Open", count: countByStatus("OPEN"), color: "text-red-600 bg-red-50" },
          { label: "Acknowledged", count: countByStatus("ACKNOWLEDGED"), color: "text-blue-600 bg-blue-50" },
          { label: "Investigating", count: countByStatus("INVESTIGATING"), color: "text-amber-600 bg-amber-50" },
          { label: "Resolved", count: countByStatus("RESOLVED"), color: "text-green-600 bg-green-50" },
          { label: "Closed", count: countByStatus("CLOSED"), color: "text-gray-500 bg-gray-50" },
        ].map(s => (
          <div key={s.label} className={`rounded-lg p-3 border border-[#D9E1E8] ${s.color}`}>
            <div className="text-2xl font-black">{s.count}</div>
            <div className="text-xs font-semibold uppercase tracking-wide">{s.label}</div>
          </div>
        ))}
      </div>

      {actionFeedback && (
        <div className="bg-green-50 border border-green-200 rounded px-4 py-2 text-xs text-green-800 font-semibold">
          ✓ {actionFeedback}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-5 gap-4">
        {/* Alert list */}
        <div className="lg:col-span-2">
          <Card padding={false}>
            <div className="px-4 py-3 border-b border-[#D9E1E8]">
              <div className="text-sm font-semibold text-[#172B3A]">Alerts ({filtered.length})</div>
            </div>
            <div className="divide-y divide-[#D9E1E8] max-h-[70vh] overflow-y-auto">
              {loading && <div className="px-4 py-8 text-center text-xs text-[#64748B]">Loading...</div>}
              {!loading && filtered.length === 0 && (
                <div className="px-4 py-8 text-center text-xs text-[#64748B]">No alerts match filter</div>
              )}
              {filtered.map(alert => (
                <div
                  key={alert.id}
                  className={cn(
                    "px-4 py-3 cursor-pointer hover:bg-[#F5F7FA] transition-colors",
                    selected?.id === alert.id && "bg-blue-50 border-l-4 border-[#145DA0]"
                  )}
                  onClick={() => setSelected(alert)}
                >
                  <div className="flex items-start justify-between gap-2 mb-1">
                    <AlertPriorityBadge priority={alert.priority} />
                    <span className="text-xs text-[#64748B]">{timeAgo(alert.created_at)}</span>
                  </div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className={cn("text-xs px-1.5 py-0.5 rounded font-semibold", SOURCE_COLORS[alert.source])}>
                      {alert.source.replace("_", " ")}
