                      {alert.status}
                    </span>
                  </div>
                  <div className="text-xs font-semibold text-[#172B3A] leading-snug">{alert.title}</div>
                </div>
              ))}
            </div>
          </Card>
        </div>

        {/* Alert detail */}
        <div className="lg:col-span-3 space-y-4">
          {selected ? (
            <>
              <Card>
                <div className="flex items-start justify-between mb-3">
                  <div>
                    <div className="flex items-center gap-2 flex-wrap mb-1">
                      <span className="text-sm font-black text-[#172B3A] font-mono">{selected.alert_id}</span>
                      <AlertPriorityBadge priority={selected.priority} size="md" />
                      <span className={cn("text-xs px-2 py-1 rounded border font-semibold", STATUS_COLORS[selected.status])}>
                        {selected.status}
