              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                {selected.track_circuit_id && (selected as any).track_circuit && (
                  <Card>
                    <div className="text-xs font-bold text-[#64748B] uppercase tracking-wide mb-2">Track Circuit</div>
                    <div className="text-sm font-bold font-mono text-[#172B3A] mb-1">{(selected as any).track_circuit.track_circuit_id}</div>
                    <TrackCircuitStatusBadge status={(selected as any).track_circuit.status} />
                    <div className="text-xs text-[#64748B] mt-1">{(selected as any).track_circuit.location_description?.substring(0, 50)}</div>
                  </Card>
                )}
                {selected.sensor_id && (selected as any).sensor && (
                  <Card>
                    <div className="text-xs font-bold text-[#64748B] uppercase tracking-wide mb-2">FBG Sensor</div>
                    <div className="text-sm font-bold font-mono text-[#172B3A] mb-1">{(selected as any).sensor.sensor_id}</div>
                    <RiskBadge risk={(selected as any).sensor.risk_level} />
                    <TrendBadge trend={(selected as any).sensor.trend} />
                    <div className="text-xs text-[#64748B] mt-1">{(selected as any).sensor.current_strain} µε ({(selected as any).sensor.percentage_change > 0 ? "+" : ""}{(selected as any).sensor.percentage_change?.toFixed(1)}%)</div>
                  </Card>
                )}
                {selected.asset_id && (selected as any).asset && (
                  <Card>
                    <div className="text-xs font-bold text-[#64748B] uppercase tracking-wide mb-2">Asset</div>
                    <div className="text-sm font-bold font-mono text-[#172B3A] mb-1">{(selected as any).asset.asset_id}</div>
                    <AssetConditionBadge condition={(selected as any).asset.condition} />
                    <div className="text-xs text-[#64748B] mt-1">{(selected as any).asset.location_description?.substring(0, 50)}</div>
                  </Card>
                )}
              </div>
            </>
          ) : (
            <Card>
              <div className="text-center py-12 text-[#64748B]">
                <div className="text-3xl mb-3">⚠</div>
                <div className="text-sm font-semibold">Select an alert</div>
                <div className="text-xs mt-1">Click an alert to view details, evidence and take action</div>
              </div>
            </Card>
          )}
        </div>
      </div>

      <Modal open={inspectionModal} onClose={() => setInspectionModal(false)} title="Create Inspection Task" size="md">
        {selected && (
          <div className="space-y-4">
            <p className="text-sm text-[#64748B]">Create a field inspection task for this alert. The inspector will receive the task with all relevant context.</p>
            <div className="bg-[#F5F7FA] border border-[#D9E1E8] rounded p-3">
              <div className="text-xs font-bold text-[#172B3A] mb-1">Alert: {selected.alert_id}</div>
              <div className="text-xs text-[#64748B]">{selected.title}</div>
            </div>
            {(selected as any).asset && (
              <div className="text-xs"><span className="text-[#64748B]">Asset: </span><span className="font-semibold">{(selected as any).asset.asset_id}</span> — {(selected as any).asset.location_description}</div>
            )}
            <div className="flex gap-2 justify-end">
              <Button variant="secondary" onClick={() => setInspectionModal(false)}>Cancel</Button>
              <Button variant="primary" onClick={handleCreateInspection}>Create Inspection Task</Button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}
