  RiskBadge, TrendBadge, Select, Textarea, Modal
} from "../components/ui";
import { fetchInspections, updateInspection, createMaintenanceTask, createInspection } from "../store/dataStore";
import { ASSETS, TRACK_CIRCUITS, FBG_SENSORS, ALERTS } from "../store/dataStore";
import { formatTimestamp, timeAgo, cn } from "../utils";
import type { Inspection } from "../types";

export function InspectionsPage() {
  const navigate = useNavigate();
