  const [observations, setObservations] = useState("");
  const [findings, setFindings] = useState("");
  const [recommendations, setRecommendations] = useState("");
  const [faultConfirmed, setFaultConfirmed] = useState(false);
  const [falseAlarm, setFalseAlarm] = useState(false);
  const [actionFeedback, setActionFeedback] = useState<string | null>(null);

  // Create inspection form state
  const [createForm, setCreateForm] = useState({
    asset_id: params.get("asset") ?? "",
    track_circuit_id: params.get("tc") ?? "",
    title: "", reason: "", priority: "WARNING" as any, location: "",
  });

  const load = () => {
    fetchInspections().then(data => {
      setInspections(data);
      setLoading(false);
      const found = data.find(i => i.id === params.get("id") || i.inspection_id === params.get("id"));
      if (found) setSelected(found);
      else if (!params.get("create")) {
        const demo = data.find(i => i.inspection_id === "INSP-001");
        if (demo) setSelected(demo);
      }
    });
