import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  Card, PageHeader, SimulatedDataBanner, Button,
  MaintenanceStatusBadge, AlertPriorityBadge, AssetConditionBadge, Select, Modal, Textarea
} from "../components/ui";
import { fetchMaintenanceTasks, updateMaintenanceTask } from "../store/dataStore";
import { ASSETS, MAINTENANCE_VERIFICATIONS } from "../store/dataStore";
import { formatTimestamp, timeAgo, cn } from "../utils";
import type { MaintenanceTask } from "../types";

const WORKFLOW_STEPS = [
  { key: "OPEN", label: "Open" },
  { key: "ASSIGNED", label: "Assigned" },
  { key: "IN_PROGRESS", label: "In Progress" },
  { key: "COMPLETED", label: "Completed" },
  { key: "VERIFICATION_REQUIRED", label: "Verification Required" },
  { key: "VERIFIED", label: "Verified" },
  { key: "CLOSED", label: "Closed" },
];

export function MaintenancePage() {
  const navigate = useNavigate();
  const [tasks, setTasks] = useState<MaintenanceTask[]>([]);
  const [selected, setSelected] = useState<MaintenanceTask | null>(null);
  const [filterStatus, setFilterStatus] = useState("active");
  const [loading, setLoading] = useState(true);
  const [verifyModal, setVerifyModal] = useState(false);
  const [verifyNotes, setVerifyNotes] = useState("");
  const [verifyPassed, setVerifyPassed] = useState(true);
  const [actionFeedback, setActionFeedback] = useState<string | null>(null);
  const [editModal, setEditModal] = useState(false);
  const [editForm, setEditForm] = useState({ assigned_technician: "", work_description: "", parts_used: "", actual_hours: "" });

  const load = () => {
    fetchMaintenanceTasks().then(data => {
      setTasks(data);
      setLoading(false);
      const demo = data.find(t => t.maintenance_id === "MAINT-001");
      if (demo) setSelected(demo);
    });
  };

  useEffect(load, []);

  const filtered = tasks.filter(t => {
    if (filterStatus === "active") return !["CLOSED", "VERIFIED"].includes(t.status);
    if (filterStatus === "closed") return ["CLOSED", "VERIFIED"].includes(t.status);
    return true;
  });

  const feedback = (msg: string) => {
    setActionFeedback(msg);
    setTimeout(() => setActionFeedback(null), 3000);
  };

  const handleStatusChange = async (task: MaintenanceTask, newStatus: string) => {
    const updates: Partial<MaintenanceTask> = { status: newStatus as any };
    if (newStatus === "IN_PROGRESS" && !task.started_at) updates.started_at = new Date().toISOString();
    if (newStatus === "COMPLETED") {
      updates.completed_at = new Date().toISOString();
      updates.status = "VERIFICATION_REQUIRED" as any;
    }
    await updateMaintenanceTask(task.id, updates);
    feedback(`Status updated to ${newStatus}`);
    load();
  };

  const handleVerify = async () => {
    if (!selected) return;
    await updateMaintenanceTask(selected.id, {
      status: verifyPassed ? "VERIFIED" : "IN_PROGRESS" as any,
    });
    setVerifyModal(false);
    feedback(verifyPassed ? "Maintenance verified and closed" : "Verification failed — task reopened");
    load();
  };

  const handleEdit = async () => {
    if (!selected) return;
    await updateMaintenanceTask(selected.id, {
      assigned_technician: editForm.assigned_technician || selected.assigned_technician,
      work_description: editForm.work_description || selected.work_description,
      parts_used: editForm.parts_used || selected.parts_used,
