                step.key === "VERIFICATION_REQUIRED" && count > 0 ? "text-orange-600" :
                "text-[#172B3A]"
              )}>{count}</div>
              <div className="text-xs text-[#64748B] font-semibold">{step.label}</div>
            </div>
          );
