                {a&&<div style={{fontSize:10,color:"var(--accent)",fontFamily:"monospace",marginTop:2}}>{a.asset_id}</div>}
                {insp.assigned_inspector&&<div style={{fontSize:10,color:"var(--text-muted)",marginTop:2}}>👤 {insp.assigned_inspector}</div>}
